pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    // Dominant bottleneck heuristic
    let dominant_bottleneck = if cpu_norm < ram_norm { cpu_norm } else { ram_norm };

    // Cross-product alignment heuristic
    let cross_product = (cpu_norm * ram_norm).sqrt();

    // Penalize resource imbalance
    let imbalance_penalty = (cpu_norm - ram_norm).abs() * step_index as f64 / total_jobs as f64;

    // Dynamic horizon awareness with non-linear conditionals
    let dynamic_horizon = if step_index < total_jobs / 2 {
        step_index as f64 / (total_jobs / 2) as f64
    } else {
        1.0 - ((step_index - total_jobs / 2) as f64 / (total_jobs / 2) as f64).powi(2)
    };

    // Lookahead awareness with packing bonuses and penalties
    let lookahead_score = if next_job_cpu == 0 && next_job_ram == 0 {
        0.0
    } else {
        let next_job_norm_cpu = (node_residual_cpu + next_job_cpu) as f64 / node_capacity_cpu as f64;
        let next_job_norm_ram = (node_residual_ram + next_job_ram) as f64 / node_capacity_ram as f64;
        let lookahead_balance = (next_job_norm_cpu - next_job_norm_ram).abs();
        if lookahead_balance < 0.1 {
            0.5 * (next_job_norm_cpu * next_job_norm_ram).sqrt()
        } else {
            -0.5 * lookahead_balance
        }
    };

    // Fine-grained residual fitting bonus
    let residual_fit_bonus = 1.0 - ((node_residual_cpu + job_cpu) as f64 / node_capacity_cpu as f64).powi(2)
                          - ((node_residual_ram + job_ram) as f64 / node_capacity_ram as f64).powi(2);

    // Combine fine-grained residual fitting with lookahead anticipation
    let combined_fit_and_lookahead = (residual_fit_bonus * dynamic_horizon) * (1.0 + lookahead_score);

    // Balance CPU and RAM usage by adjusting the score
    let cpu_ram_balance = 1.0 - ((cpu_norm - ram_norm).abs() / (mean_cpu_residual / mean_ram_residual));

    // Final score combining all factors with CPU-RAM balance adjustment
    let score = dominant_bottleneck * cross_product 
                - imbalance_penalty * dynamic_horizon 
                + combined_fit_and_lookahead 
                * cpu_ram_balance;

    score
}

